challenges.solutionCode:
function validarEdad(edad) {
  return Number.isInteger(edad) && edad >= 18 && edad <= 120;
}

test("acepta limite inferior", () => {
  expect(validarEdad(18)).toBeTruthy();
});

test("acepta limite superior", () => {
  expect(validarEdad(120)).toBe(true);
});

test("rechaza valores fuera de rango", () => {
  expect(validarEdad(17)).toBeFalsy();
  expect(validarEdad(121)).toBe(false);
  expect(validarEdad(18.5)).toBe(false);
});

