challenges.solutionCode:
async function obtenerPrecio(catalogo, id) {
  const producto = catalogo.find(item => item.id === id);
  if (!producto) throw new Error("Producto inexistente");
  return producto.precio;
}

test("devuelve precio existente", async () => {
  const precio = await obtenerPrecio([{ id: 1, precio: 250 }], 1);
  expect(precio).toBe(250);
});

test("rechaza producto ausente", async () => {
  try {
    await obtenerPrecio([], 99);
    throw new Error("La promesa debía rechazarse");
  } catch (error) {
    expect(error.message).toBe("Producto inexistente");
  }
});

