challenges.solutionCode:
async function guardarPedido(pedido, repositorio) {
  return repositorio.guardar(pedido);
}

test("delegar guardado al repositorio", async () => {
  const pedido = { id: 10, total: 99 };
  const guardar = vi.fn(async valor => ({ ...valor, guardado: true }));
  const resultado = await guardarPedido(pedido, { guardar });
  expect(resultado.guardado).toBe(true);
  expect(guardar).toHaveBeenCalledTimes(1);
  expect(guardar).toHaveBeenCalledWith(pedido);
});
